# Try with different March 2003 CPI estimates and see sensitivity
import statistics

# Annual CPI values from system prompt
annual_cpi = {2000: 172.2, 2001: 177.1, 2002: 179.9}

# ESF data in thousands
june_data = {
    2000: {'total_assets': 38750276, 'fe_sec': 15512432},
    2001: {'total_assets': 34996129, 'fe_sec': 14413541},
    2002: {'total_assets': 37619185, 'fe_sec': 16078533},
}
sept_data = {
    2000: {'total_assets': 37094883, 'fe_sec': 15603059},
    2001: {'total_assets': 36353790, 'fe_sec': 15293964},
    2002: {'total_assets': 37591058, 'fe_sec': 16045532},
}

def compute_diff(cpi_target):
    june_shares = []
    sept_shares = []
    for year in [2000, 2001, 2002]:
        adj = cpi_target / annual_cpi[year]
        june_shares.append(june_data[year]['fe_sec'] * adj / (june_data[year]['total_assets'] * adj) * 100)
        sept_shares.append(sept_data[year]['fe_sec'] * adj / (sept_data[year]['total_assets'] * adj) * 100)
    return abs(statistics.mean(june_shares) - statistics.mean(sept_shares))

# Test various March 2003 CPI estimates
for cpi in [183.0, 183.5, 184.0, 184.5, 185.0]:
    d = compute_diff(cpi)
    print(f"CPI_Mar2003={cpi}: diff={d:.6f}")

print(f"\nNominal diff (no CPI adjustment): {compute_diff(1.0):.6f}")
